function cleanJson(s: string): string {
  return s.replace(/,\s*]/g, ']').replace(/,\s*}/g, '}').replace(/([{,]\s*)([A-Za-z0-9_]+)\s*:/g, '$1"$2":').replace(/'/g, '"');
