function parseVarArray(html: string, varName: string): any[] {
  const re = new RegExp(`var\\s+${varName}\\s*=\\s*(\\[\\[\\\\s\\\\S]*?\\]);`);
  // fallback za { } ili [[ ]]
  let m = html.match(new RegExp(`var\\s+${varName}\\s*=\\s*(\\[\\[?[\\s\\S]*?\\]\\]?);`));
  if (!m) {
    m = html.match(new RegExp(`var\\s+${varName}\\s*=\\s*(\\{[\\s\\S]*?\\});`));
