export interface OfficialForecast { issuedAt?: string; days: { title?: string; text: string; issuedAt?: string; image?: string }[]; seafarer?: { text: string; image?: string; issuedAt?: string }; rawHtml: string; }

function stripHtml(html: string): string {
  return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

export function parseOfficial(html: string): OfficialForecast {
  const days: { title?: string; text: string; issuedAt?: string; image?: string }[] = [];
  // nadji sve prognoza-title + prognoza-text + prognoza-sign grupe
  const re = /<div class="prognoza-title">\s*([^<]+?)\s*<\/div>\s*<div class="prognoza-text">\s*([\s\S]*?)\s*<\/div>\s*<div class="prognoza-sign"[^>]*>\s*([^<]+?)\s*<\/div>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(html)) !== null) {
    const title = stripHtml(m[1]);
    const text = stripHtml(m[2]);
    const issuedAt = stripHtml(m[3]);
    // nadji sliku poslije ovog bloka
    const after = html.slice(m.index! + m[0].length, m.index! + m[0].length + 2000);
    const imgM = after.match(/<img[^>]+src="([^"]+cgprognoza[^"]*)"/);
    const image = imgM ? imgM[1] : undefined;
    if (text.length > 20) days.push({ title, text: text.slice(0, 1200), issuedAt, image });
  }
  // za pomorce
  let seafarer: { text: string; image?: string; issuedAt?: string } | undefined;
  const seaRe = /Prognoza za pomorce[\s\S]*?<div class="prognoza-text">\s*([\s\S]*?)\s*<\/div>/i;
  const seaM = html.match(seaRe);
  if (seaM) {
    const t = stripHtml(seaM[1]);
    const imgM = html.slice(seaM.index! + seaM[0].length, seaM.index! + seaM[0].length + 2000).match(/<img[^>]+src="([^"]+jjadran[^"]*)"/);
    seafarer = { text: t.slice(0, 1200), image: imgM ? imgM[1] : undefined };
  }
  // fallback za pomorce ako je drugacije
  if (!seafarer) {
    const idx = html.toLowerCase().indexOf('za pomorce');
    if (idx !== -1) {
      const snippet = html.slice(idx, idx+2000);
      const t = stripHtml(snippet);
      if (t.length > 20) seafarer = { text: t.slice(0, 1000) };
    }
  }
  const firstIssued = days[0]?.issuedAt;
  return { issuedAt: firstIssued, days, seafarer, rawHtml: html.slice(0, 2000) };
}
