export interface NumericalHour { utcHour: string; symbol?: string; rrMm?: number; rhPct?: number; windCode?: string; }
export interface NumericalDay { date?: string; tmin?: number; tmax?: number; hours: NumericalHour[]; model: string; city: string; }
function toNum(s: string): number | undefined {
  const n = Number(s.replace(',', '.').replace('−','-').trim());
  return Number.isFinite(n) ? n : undefined;
}
function strip(s: string): string { return s.replace(/<[^>]+>/g,'').trim(); }
export function parseNumerical(html: string, city: string, model: string): NumericalDay {
  const tminM = html.match(/Tmin[^<]*<\/[^>]+>\s*<[^>]+>\s*([^<]+?)\s*</i);
  const tmaxM = html.match(/Tmax[^<]*<\/[^>]+>\s*<[^>]+>\s*([^<]+?)\s*</i);
  const tmin = tminM ? toNum(strip(tminM[1])) : undefined;
  const tmax = tmaxM ? toNum(strip(tmaxM[1])) : undefined;
  const dateM = html.match(/(\d{4}-\d{2}-\d{2})|(\d{2}\.\d{2}\.\d{4})/);
  const date = dateM ? dateM[0] : undefined;
  // nadji red sa satima 00 03 06...
  const hours: NumericalHour[] = [];
  const rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
  let m: RegExpExecArray | null;
  const rows: string[] = [];
  while((m=rowRe.exec(html))!==null) rows.push(m[1]);
  // nadji red koji ima RR (mm) pa su ispod simboli
  for(let i=0;i<rows.length;i++){
    if(/RR\s*\(mm\)/i.test(rows[i])){
      // sljedeci redovi su simboli, RR, RH, vjetar
      // simboli su u <img src=".../Simbolcici/.../01.svg">
      // RR su brojevi
    }
  }
  // jednostavnije: izvuci sve simbole i RR/RH/vjetar po kolonama
  const simbols = [...html.matchAll(/Simbolcici\/([^"]+\.svg)/gi)].map(x=> x[1].replace('.svg',''));
  const rrMatches = [...html.matchAll(/<td[^>]*>\s*(-?\d+(?:[.,]\d+)?)\s*<\/td>\s*<td[^>]*>\s*(-?\d+(?:[.,]\d+)?)\s*<\/td>/gi)];
  // za sada uzmi 8 termina hardkodirano 00,03,06,09,12,15,18,21
  const times = ["00","03","06","09","12","15","18","21"];
  for(let i=0;i<8;i++){
    const sym = simbols[i] || undefined;
    // RR i RH su u istom redu, ali cemo ih izvuci iz tabele
    const rrM = html.match(new RegExp(`<td[^>]*>\\s*${times[i]}[^<]*<\\/td>[\\s\\S]*?<td[^>]*>\\s*([^<]+?)\\s*<\\/td>`, 'i'));
    hours.push({ utcHour: times[i], symbol: sym, rrMm: undefined, rhPct: undefined, windCode: undefined });
  }
  // bolje: parsiraj cijelu tabelu kao matricu
  return { date, tmin, tmax, hours, model, city };
}
