**Sledeći 1 mali korak — cron koji svakih 3 sata puni 250 linkova u bazu:**

Nalijepi ovo:
```bash
cat > src/jobs/numericalCron.ts <<'EOF'
import { buildNumericalUrl } from '../sources/numerical/urls';
import { parseNumerical } from '../sources/numerical/parseNumerical';
import { NUMERICAL_STATIONS } from '../sources/numerical/stations';
import { zhmsFetch } from '../lib/http';

export async function runNumericalCron(db: D1Database): Promise<{ ok: number; fail: number }> {
  let ok=0, fail=0;
  const cities = Object.keys(NUMERICAL_STATIONS);
  for(const city of cities){
    for(const model of ["e3km","a3km"] as const){
      for(let day=1; day<=5; day++){
        const url = buildNumericalUrl(model as any, city as any, day);
        try{
          const res = await zhmsFetch(url);
          const html = await res.text();
          const parsed = parseNumerical(html, city, model);
          const now = new Date().toISOString();
          const r = await db.prepare(`INSERT INTO numerical_days (city, model, day_num, date, tmin, tmax, fetched_at) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(city, model, day_num) DO UPDATE SET date=excluded.date, tmin=excluded.tmin, tmax=excluded.tmax, fetched_at=excluded.fetched_at RETURNING id`).bind(city, model, day, parsed.date||null, parsed.tmin??null, parsed.tmax??null, now).first() as any;
          const dayId = r?.id ?? (await db.prepare(`SELECT id FROM numerical_days WHERE city=? AND model=? AND day_num=?`).bind(city, model, day).first() as any)?.id;
          if(!dayId) continue;
          await db.prepare(`DELETE FROM numerical_hours WHERE day_id=?`).bind(dayId).run();
          for(const h of parsed.hours){
            await db.prepare(`INSERT INTO numerical_hours (day_id, utc_hour, symbol, rr_mm, rh_pct, wind_code) VALUES (?, ?, ?, ?, ?, ?)`).bind(dayId, h.utcHour, h.symbol||null, h.rrMm??null, h.rhPct??null, h.windCode||null).run();
          }
          ok++;
        }catch(e){ fail++; }
        // postuj da ne opteretimo ZHMS
        await new Promise(r=> setTimeout(r, 120));
      }
    }
  }
  return { ok, fail };
}
