function weatherDescription(code,clouds,VBNobl=0) {
	var nebo=["Vedro","Prete��no vedro","Malo obla�?no","Umjereno obla�?no","Prete��no obla�?no","Obla�?no"]
	if(code==null || code==undefined || code<4 ) {
		if(clouds <2) return nebo[0];
		else if(clouds <3) return  (VBNobl==9? nebo[0]:nebo[1]);
		else if(clouds <5) {return  (VBNobl==9? nebo[1]:nebo[2]);//console.log(code+' '+clouds+' '+VBNobl+' '+(VBNobl==9));
		}
		else if(clouds < 7) return (VBNobl==9? nebo[2]:nebo[3]);
		else if(clouds < 8) return (VBNobl==9? nebo[3]:nebo[4]);
		else return (VBNobl==9? nebo[4]:nebo[5]);
	}
	else return opisiPojava[code];	
}



function weatherSymbol(code, clouds,VBNobl=0){
	
	if(clouds=='-') return 0;
	var correction=0;
	if(VBNobl==9) var correction=-1;

	if(code==null || code==undefined || code<4) {
		if(clouds <3) return 1;
		else if(clouds <5) return 2;
		else if(clouds < 7) return 3;
		else return 4;
	}
		
	if(code==30 || (code>=36 && code <=39)) return 24;
	
	if(code>20 && code<30){	
		if(code==21 || code==24) 
			return (clouds > 6 ? 7 : 5);
		else if(code==25 || code==27) 
			return ( clouds>6 ? 8 : 6);
		else if(code==22) 
			return ( clouds>6 ? 15 : 14);
		else if(code==23 || code==26) 
			return ( clouds>6 ? 18 : 17);
		else if(code==28) 
			return ( clouds>6 ? 20 : 19);
		else if(code==29) 
			return ( clouds>6 ? 10 : 21);
	}
	else if(code<=40) {
		return (clouds<3 ? 1: (code<5 ? 2 : (code>6 ? 4 : 3)))+correction;
	}
	else if(code<50) {
		if(clouds<=6) 
			if(code==41 || code==44 || code==46 || code==48)
				return 19;
		return 20;	
	}
	else if(code<70) {
		if(code==68 || code==69) 
			return (clouds>6?18:17);
		else if(clouds<7){
			if((code>51 && code<56) || (code==57 || code==59 || code==67)) 
				return 6;
			else 
				return 5;
		}
		else{
			if(code==64 || code==65) 
				return 9;
			else if(code<=53 || (code==56 || code==58 || code==60 || code==61 || code==66)) 
				return 7;
			else 
				return 8;
		}
	}
	else {
		if(code==79 || code==87 || code==88 || code==93 || code==94 ||  code==97 ||  code==99){
			return (clouds>6?23:22);
 		}
		else if(code==80 || code==89) 
			return (clouds>6 ? 7 : 5);
		else if(code==81 || code==82 || code==90){
			if(clouds<7) 
				return 6; 
			else 
				return (code==82 ? 9 : 8);
		}
		else if(code==83) 
			return (clouds>6 ? 18 : 17);
		else if(code<87) 
			if(clouds < 7) 
				return 14;
			else {
				if((code>71 && code<76) || code==86) 
					return 16;
				else if(code==84) 
					return 18;
				else 
					return 15;
			}
		else if(code==91 || code==92 || code==95 || code==96) 
				return (clouds>6? 13 : (code==92 ? 12 : 11));
			else 
				return (clouds>6?10:21);;
	}
