  return m ? m[1].trim() : "";
}

function parseSeaTable(htmlSnippet: string, timeRaw: string): SeaPoint[] {
  const out: SeaPoint[] = [];
  const re = /<tr[^>]*>[\s\S]*?<td[^>]*>([^<]+)<\/td>\s*<td[^>]*>([^<]+)<\/td>/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(htmlSnippet)) !== null) {
