function mockDb() {
  const vals: Record<string, any> = { H: { ts: 111, value: 31 }, P: { ts: 111, value: 1009 }, GR: { ts: 111, value: 200 } };
  return {
    prepare: (sql: string) => ({
      bind: (...args: any[]) => ({
        all: async () => {
          if (String(sql).includes('station_timeseries')) {
            const param = args[1];
            const v = vals[param];
            return { results: v ? [v] : [] };
          }
          return { results: [] };
        },
        first: async () => null,
        run: async () => {},
      }),
    }),
  } as any;
}
