Može. Merimo 48h pa prag — isto kao za numeričku, samo za grafik.

```bash
cat > migrations/0007_graph_log.sql <<'EOF'
CREATE TABLE IF NOT EXISTS graph_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  station_id TEXT NOT NULL,
  graph_tip TEXT NOT NULL,
  last_modified TEXT,
  etag TEXT,
  checked_at TEXT NOT NULL,
  status TEXT
);
CREATE INDEX IF NOT EXISTS idx_graph_log_checked ON graph_log(checked_at);
EOF
cat > src/jobs/graphLogger.ts <<'EOF'
import { buildGraphUrl } from '../sources/zhms-aws/fetchGraph';

const SAMPLE: { id: string; tips: ("G1" | "G3")[] }[] = [
  { id: "02PDGR10", tips: ["G1", "G3"] },
  { id: "02BERA20", tips: ["G1", "G3"] },
  { id: "02DANL20", tips: ["G1", "G3"] },
  { id: "02LKOT20", tips: ["G1", "G3"] },
];

export async function logGraphSentinel(db: D1Database): Promise<void> {
  const now = new Date().toISOString();
  for (const s of SAMPLE) {
    for (const tip of s.tips) {
      const url = buildGraphUrl(tip as any, s.id);
      try {
        let lastMod: string | null = null;
        try {
          const row = await db.prepare(`SELECT last_modified FROM graph_log WHERE station_id=? AND graph_tip=? ORDER BY checked_at DESC LIMIT 1`).bind(s.id, tip).first() as any;
          lastMod = row?.last_modified || null;
        } catch {}
        const headers: Record<string, string> = {};
        if (lastMod) headers["If-Modified-Since"] = lastMod;
        const res = await fetch(url, { method: "GET", headers });
        const lm = res.headers.get("last-modified") || res.headers.get("Last-Modified") || lastMod;
        const etag = res.headers.get("etag") || res.headers.get("ETag") || null;
        await db.prepare(`INSERT INTO graph_log (station_id, graph_tip, last_modified, etag, checked_at, status) VALUES (?, ?, ?, ?, ?, ?)`).bind(s.id, tip, lm, etag, now, String(res.status)).run();
      } catch (e: any) {
        await db.prepare(`INSERT INTO graph_log (station_id, graph_tip, last_modified, etag, checked_at, status) VALUES (?, ?, ?, ?, ?, ?)`).bind(s.id, tip, null, null, now, "error:" + String(e?.message ?? e).slice(0, 120)).run();
      }
    }
  }
}
EOF
