  return {
    rows,
    prepare: (sql: string) => ({
      bind: (...args: any[]) => ({
        all: async () => ({ results: [] }),
        first: async () => null,
        run: async () => { rows.push({ sql, args }); },
      }),
    }),
  } as any;
}
